<?php $url = (string) ($_ENV['URL_ADM'] ?? ''); $perms = $this->data['buttonPermission'] ?? []; ?>
<div class="container-fluid px-4"><div class="d-flex justify-content-between align-items-center mt-4 mb-3"><h1 class="h3">Autorizações</h1><?php if (in_array('PortariaAutorizacoesCreate', $perms, true)): ?><a class="btn btn-success" href="<?= $url ?>portaria-autorizacoes-create">Nova autorização</a><?php endif; ?></div>
<div class="card shadow-sm"><div class="card-body"><?php include './app/adms/Views/partials/alerts.php'; ?><form method="get" class="row g-2 mb-3"><div class="col-md-6"><input class="form-control" name="busca" value="<?= htmlspecialchars((string) ($this->data['filters']['busca'] ?? '')) ?>" placeholder="Protocolo, visitante ou anfitrião"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">Todos os status</option><?php foreach (['aguardando','autorizada','recusada','cancelada'] as $s): ?><option <?= ($this->data['filters']['status'] ?? '') === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filtrar</button></div></form>
